def solve_large():
    a = [0] * 4097
    a[1] = 1
    a[2] = 1
    for n in range(3, 4097):
        a[n] = a[a[n-1]] + a[n - a[n-1]]

    powers_of_2 = []
    for k in range(13):
        n = 2**k
        if n < 4097:
            powers_of_2.append((n, a[n]))

    return powers_of_2

print(solve_large())
